import numpy as np
# Independent Eratosthenes sieve, fully from scratch
def pi_sieve(N):
    if N < 2: return 0
    s = np.ones(N+1, dtype=bool); s[:2] = False
    for i in range(2, int(N**0.5)+1):
        if s[i]:
            s[i*i::i] = False
    return int(s.sum())
for k in (24,25,26):
    N = 2**k - 1
    print(f"pi(2^{k}-1) = pi({N}) = {pi_sieve(N)}")
PY
